SELECT 
FROM notes
WHERE visibility = 1 AND id < #{cursor}

/* P18 屏蔽双向过滤：屏蔽者与被屏蔽者互不可见 */
AND NOT EXISTS (SELECT 1 FROM user_blocks b
                WHERE (b.user_id = #{viewerId} AND b.blocked_user_id = notes.user_id)
                   OR (b.user_id = notes.user_id AND b.blocked_user_id = #{viewerId}))

ORDER BY id DESC
LIMIT #{limit}

SELECT FROM notes WHERE user_id = #{userId} AND id < #{cursor}
/* P18：被屏蔽者看屏蔽者的网格为空（双向） */ AND NOT EXISTS (SELECT 1 FROM user_blocks b WHERE (b.user_id = #{viewerId} AND b.blocked_user_id = notes.user_id) OR (b.user_id = notes.user_id AND b.blocked_user_id = #{viewerId}))
AND visibility IN (0, 1) AND visibility = 1
ORDER BY id DESC LIMIT #{limit}
